const text = String(query || '').toLowerCase();
const critical = /unauthori[sz]ed|without my permission|used my card|didn.?t (make|place|approve)|stolen|hacked|account takeover|password (leak|stol|comprom)|fraud|scam|phish|otp|one.time code|card (number|details) (leak|expos|stol)/i;
const urgent = /charged twice|double charg|refund.{0,24}(missing|overdue)|locked out|can't log in|cannot log in|lost package|never arrived|order.{0,30}not arrived/i;
const band = critical.test(text) ? 'critical' : urgent.test(text) ? 'priority' : 'routine';
const reasons = band === 'critical' ? ['Possible fraud or account-security concern'] : band === 'priority' ? ['Payment, access, or delivery concern needing staff review'] : ['No immediate security indicator detected'];
const nextSteps = band === 'critical' ? ['Do not share credentials or full payment details', 'Contact official retailer support and your bank via verified channels', 'Request a human security review'] : band === 'priority' ? ['Ask staff to check the order or account through a verified channel', 'Keep order reference ready; do not post it publicly'] : ['Provide general guidance', 'Have staff verify order-specific status if needed'];
return JSON.stringify({ band, reasons, nextSteps, limitation: 'Keyword triage only; no account or transaction lookup was performed.' });
